#!/usr/bin/env python3
"""Reproduce the manually reviewed policy slice. No generated inference or inferred joins."""
import json,pathlib,re
R=pathlib.Path(__file__).resolve().parents[4]
OUT=R/'research/raw/atlas-expansion/policy.json'
D={'sources':[],'entities':[],'relationships':[],'records':[],'localities':[]}
def source(id,title,publisher,date,locator,summary,tier='documented',limitations=None,url=None):
 receipt=pathlib.Path(__file__).parent/(id+'.receipt.json')
 if url is None:url=json.load(open(receipt))['url']
 D['sources'].append(dict(id=id,title=title,url=url,publisher=publisher,publishedAt=date,retrievedAt='2026-10-07',locator=locator,summary=summary,tier=tier,limitations=(limitations or [])+[f'Archive: research/raw/atlas-expansion/policy-evidence/{id}.receipt.json; original bytes and extracted text are distinct artifacts.']))
def geo(src,state=None,local=None,note=None):
 return [{'scope':'city' if local else ('state' if state else 'national'),'stateCodes':[state] if state else [],'localityIds':[local] if local else [],'basis':'project-location' if state else 'national-context','note':note or ('Dated project location; no statewide spending inferred.' if state else 'National legal or institutional context; no allocation to every state inferred.'),'sourceIds':src}]
def dims(src,domain,route,layers=None,g=None,limitations=None):
 return dict(sourceIds=src,domains=domain,layers=layers or ['policy','legal'],route=route,geography=g or geo(src),limitations=limitations or [])
def entity(id,label,type,src,domain,route,summary,basis=None,canonical=None,g=None):
 x=dict(id=id,label=label,type=type,resolved=True,identityBasis=basis or 'Exact institution or instrument named in the cited primary document.',summary=summary,**dims(src,domain,route,['organisations','policy','legal'],g))
 if canonical:x['canonicalId']=canonical
 D['entities'].append(x)
def amount(value,unit,stage,period,currency='INR'):return dict(value=value,currency=currency,unit=unit,stage=stage,period=period)
def edge(id,a,b,label,kind,date,src,domain,route,summary,records=None,responses=None,amounts=None,tier='documented',status=None,g=None,limits=None,end=None):
 D['relationships'].append(dict(id=id,from_=a,to=b,kind=kind,label=label,tier=tier,status=status or 'documented dated relationship',statusAsOf=date,fromDate=date,toDate=end or date,dateBasis='Dated legal, contract or disclosure event; an instantaneous event is not an ongoing ownership assertion.',summary=summary,alternativeExplanations=['A lawful policy, contract or financing relationship does not by itself establish preferential treatment or wrongdoing.'],falsifier='A corrected original instrument identifying a different legal party, date, scope or financial stage would require amendment of this relationship.',responseIds=responses or [],recordIds=records or [],amounts=amounts or [],**dims(src,domain,route,['policy','organisations','funding','legal'],g,limits)))
 D['relationships'][-1]['from']=D['relationships'][-1].pop('from_')
def record(id,title,summary,kind,date,src,entities,edges,domain,route,response,alternatives,falsifier,amounts=None,tier='documented',status='documented historical event',asof=None,end=None,g=None,limits=None,period=None):
 D['records'].append(dict(id=id,title=title,summary=summary,kind=kind,tier=tier,status=status,statusAsOf=asof or date,fromDate=date,toDate=end or date,dateBasis='Event/commencement date is distinct from publication, retrieval and later outcome dates; see period.',entityIds=entities,relationshipIds=edges,period=period or date,response=response,alternativeExplanations=alternatives,falsifier=falsifier,amounts=amounts or [],**dims(src,domain,route,['policy','legal','funding','review'],g,limits)))

